/** Matches RFQ codes generated by dealerRequests.generateRequestCode (REQ- + 6 chars). */
export const DEALER_REQ_CODE_RE = /REQ-[A-HJ-NP-Z2-9]{6}/i;

export function extractDealerRequestCode(text) {
  const match = String(text || '').match(DEALER_REQ_CODE_RE);
  return match ? match[0].toUpperCase() : null;
}

export function isDealerReplyMessage(text) {
  return Boolean(extractDealerRequestCode(text));
}
